    private fun sectionFor(id: Int): Int = when (id) {
        in 551..560 -> 6
        in 561..570 -> 7
        in 571..580 -> 8
        in 581..590 -> 9
        else -> 10
    }

    fun closingLines(id: Int): List<DialogueLine> = when (sectionFor(id)) {
        6 -> listOf(
            DialogueLine("A", "Makes sense. Keep me posted.", "좋아요. 진행 상황 알려주세요."),
            DialogueLine("B", "Will do.", "그럴게요.")
        )
        7 -> listOf(
            DialogueLine("A", "That sounds like a solid plan.", "괜찮은 계획 같아."),
            DialogueLine("B", "I'm trying to be more intentional about it.", "좀 더 생각해서 결정하려고 하고 있어.")
        )
        8 -> listOf(
            DialogueLine("A", "Thanks for saying that directly.", "직접 말해줘서 고마워."),
            DialogueLine("B", "I wanted to be clear without making it a bigger issue.", "일을 더 키우지 않으면서 분명하게 말하고 싶었어.")
        )
        9 -> listOf(
            DialogueLine("A", "Fair point. I can see that.", "일리 있네. 그 관점은 이해돼."),
            DialogueLine("B", "Yeah, I just want to look at the whole picture.", "응, 나는 전체를 보고 판단하고 싶어.")
        )
        else -> listOf(
            DialogueLine("A", "That sounds practical.", "현실적인 방법 같아."),
            DialogueLine("B", "I'm trying to use it in a way that actually helps me grow.", "실제로 성장에 도움이 되는 방식으로 해보려고 해.")
        )
    }
